<template><div v-loading="loading" class="app-container"><div class="page-header"><div><h1>{{ data?data.user.name:'User Detail' }}</h1><p v-if="data">{{ data.user.id }} · Commercialization roadmap phases are marked on each tab.</p></div><div class="page-actions"><el-button @click="$router.push('/commercialization/users')">Back</el-button><el-button @click="load">Refresh</el-button></div></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><template v-if="data"><div class="user-summary"><span><strong>{{ data.effective.base.name }}</strong> · v{{ data.effective.base.version }}</span><span>{{ data.effective.additional.length }} Additional</span><span><strong>{{ data.wallet.available }}</strong> available Legacy Credits</span><span>{{ data.assets.length }} saved assets</span></div><el-tabs v-model="tab"><el-tab-pane name="rights"><span slot="label">Effective Rights <el-tag size="mini" type="success" aria-hidden="true">MVP</el-tag></span><el-table :data="data.effective.items" row-key="code" border><el-table-column prop="name" label="Entitlement" min-width="220"/><el-table-column label="Authorization" min-width="160"><template slot-scope="s"><span v-if="s.row.type==='feature_access'&&!s.row.scopes.length">Feature available</span><el-tag v-for="scope in s.row.scopes" :key="scope" size="mini">{{ displayScope(s.row.code,scope) }}</el-tag></template></el-table-column><el-table-column label="Sources" min-width="300"><template slot-scope="s"><div v-for="source in s.row.sources" :key="source.grantId">{{ source.name }} v{{ source.version }} · {{ source.type }} · {{ dateTime(source.expiresAt) }}</div></template></el-table-column></el-table><h3>Grant History &amp; Scheduled Periods</h3><el-table :data="data.grants" row-key="id" border><el-table-column label="Suit" min-width="190"><template slot-scope="s">{{ s.row.name }} · v{{ s.row.version }}<div class="item-code">{{ s.row.id }}</div></template></el-table-column><el-table-column prop="source" label="Source" min-width="160"/><el-table-column prop="type" label="Type" width="100"/><el-table-column label="Starts" min-width="170"><template slot-scope="s">{{ dateTime(s.row.startsAt) }}</template></el-table-column><el-table-column label="Ends" min-width="170"><template slot-scope="s">{{ dateTime(s.row.expiresAt) }}</template></el-table-column><el-table-column prop="status" label="Status" width="95"/></el-table></el-tab-pane><el-tab-pane name="wallet"><span slot="label">Wallet &amp; Batches <el-tag size="mini" type="warning" aria-hidden="true">P1</el-tag></span><wallet :wallet="data.wallet" :user-id="data.user.id" @changed="load"/></el-tab-pane><el-tab-pane name="ledger"><span slot="label">Credits Ledger <el-tag size="mini" type="warning" aria-hidden="true">P1</el-tag></span><records-table kind="ledger" :rows="data.ledger" :show-user="false"/></el-tab-pane><el-tab-pane name="orders"><span slot="label">Orders <el-tag size="mini" type="success" aria-hidden="true">MVP</el-tag></span><records-table kind="orders" :rows="data.orders" :show-user="false" @changed="load"/></el-tab-pane><el-tab-pane name="subscriptions"><span slot="label">Subscriptions <el-tag size="mini" type="success" aria-hidden="true">MVP</el-tag></span><records-table kind="subscriptions" :rows="data.subscriptions" :show-user="false" @changed="load"/></el-tab-pane><el-tab-pane name="redemptions"><span slot="label">Redemptions <el-tag size="mini" type="info" aria-hidden="true">P3</el-tag></span><records-table kind="redemptions" :rows="data.redemptions" :show-user="false"/></el-tab-pane><el-tab-pane name="usage"><span slot="label">Service Requests <el-tag size="mini" type="warning" aria-hidden="true">P1</el-tag></span><records-table kind="usage" :rows="data.requests" :show-user="false" @changed="load"/></el-tab-pane><el-tab-pane name="assets"><span slot="label">Saved Assets <el-tag size="mini" type="success" aria-hidden="true">MVP</el-tag></span><el-alert title="Membership expiry and low Credits do not remove these assets. Reading does not create a new service charge." type="info" :closable="false" class="module-notice"/><el-table :data="data.assets" row-key="id" border><el-table-column prop="title" label="Title"/><el-table-column prop="type" label="Type" width="130"/><el-table-column label="Created" width="185"><template slot-scope="s">{{ dateTime(s.row.createdAt) }}</template></el-table-column><el-table-column label="Action" width="90"><template slot-scope="s"><el-button type="text" @click="asset=s.row">Read</el-button></template></el-table></el-tab-pane></el-tabs></template><el-dialog v-if="asset" :title="asset.title" :visible="!!asset" width="650px" @close="asset=null"><p class="asset-body">{{ asset.body }}</p></el-dialog></div></template>
<script>
import {getUser} from '@/api/commerce'
import {dateTime,scopeLabel} from '@/utils/format'
import {getCatalog} from '@/api/commercialization'
import RecordsTable from '@/components/Commerce/RecordsTable'
import Wallet from '@/components/Commerce/Wallet'

export default{components:{RecordsTable,Wallet},data(){return{data:null,catalog:[],tab:this.$route.query.tab||'rights',loading:false,error:'',asset:null}},created(){this.load()},methods:{dateTime,displayScope(code,value){return scopeLabel(this.catalog.find(item=>item.code===code)||{scopes:[]},[value])},async load(){this.loading=true;try{const [data,catalog]=await Promise.all([getUser(this.$route.params.id),this.catalog.length?Promise.resolve(this.catalog):getCatalog().catch(()=>[])]);this.data=data;this.catalog=catalog;this.error=''}catch(e){this.error=e.message}finally{this.loading=false}}}}
</script>
